import{_ as a,a as t,b as o,c as s,d as r}from"./chunks/device-tablet-landscape.D4FvTdpl.js";import{_ as n,o as i,c as l,a2 as h}from"./chunks/framework.Dx-TCpNt.js";const _=JSON.parse('{"title":"On Different Devices","description":"One app, several shapes. KomaYomi reflows instead of hiding features behind a separate mobile build, so the same buttons are always somewhere on screen —…","frontmatter":{"description":"One app, several shapes. KomaYomi reflows instead of hiding features behind a separate mobile build, so the same buttons are always somewhere on screen —…"},"headers":[],"relativePath":"guide/devices.md","filePath":"guide/devices.md","lastUpdated":1794778665000}'),p={name:"guide/devices.md"};function d(c,e,g,u,b,w){return i(),l("div",null,[...e[0]||(e[0]=[h('<h1 id="on-different-devices" tabindex="-1">On Different Devices <a class="header-anchor" href="#on-different-devices" aria-label="Permalink to &quot;On Different Devices&quot;">​</a></h1><p>One app, several shapes. KomaYomi reflows instead of hiding features behind a separate mobile build, so the same buttons are always somewhere on screen — they just move around. This page shows how the main windows rearrange at each size, with a real capture for each shape.</p><h2 id="pc-landscape-—-1440-px" tabindex="-1">PC, landscape — 1440 px <a class="header-anchor" href="#pc-landscape-—-1440-px" aria-label="Permalink to &quot;PC, landscape — 1440 px&quot;">​</a></h2><figure class="shot"><img src="'+a+'" alt="1440 px wide window with the library sidebar, three compare panes and the notes column"><figcaption>1440 px: sidebar on the left, three language panes in the middle, notes column on the right.</figcaption></figure><p>At 1440 px the sidebar (around 240 px), the compare stage and the notes column are all visible at once. The three language panes sit side by side, so a whole exchange fits without scrolling, and the notes column stays open above 1180 px — drag its splitter to widen it, or close it with <strong>Notes</strong> (<code>N</code>).</p><h2 id="pc-portrait-—-900-×-1200" tabindex="-1">PC, portrait — 900 × 1200 <a class="header-anchor" href="#pc-portrait-—-900-×-1200" aria-label="Permalink to &quot;PC, portrait — 900 × 1200&quot;">​</a></h2><figure class="shot"><img src="'+t+'" alt="900 by 1200 narrow desktop window with the library collapsed into a drawer and the compare panes stacked"><figcaption>900 × 1200: sidebar folded into a drawer, one compare column, notes closed until you ask for them.</figcaption></figure><p>At 900 px the layout switches to its narrow mode: the library folds into a drawer behind the ☰ button, the compare panes stack in a single column, and the notes column starts closed — <strong>Notes</strong> brings it back. Toolbar groups drop their text labels, and the actions that no longer fit move under <strong>More</strong>.</p><h2 id="phone-portrait-—-390-×-844" tabindex="-1">Phone, portrait — 390 × 844 <a class="header-anchor" href="#phone-portrait-—-390-×-844" aria-label="Permalink to &quot;Phone, portrait — 390 × 844&quot;">​</a></h2><figure class="shot"><img src="'+o+'" alt="390 by 844 phone window with one compare column, language chips and a toolbar wrapped over several rows"><figcaption>390 × 844: one compare column; the Language chips pick JA, EN or ZH; the toolbar wraps onto several rows.</figcaption></figure><p>On a 390 px phone the top bar wraps into three rows — navigation and page controls, then interface language and export, then the <strong>Panels / Compare</strong> switch. The compare stage keeps a single column: each panel lists its chosen languages one below another, and the <strong>Language</strong> chips (JA / EN / ZH) decide which of them appear, because there is no room for two panes side by side. Toolbar groups wrap onto extra rows instead of scrolling out of reach, and the library and notes both open as full-width drawers.</p><h2 id="tablet-portrait-—-820-×-1180" tabindex="-1">Tablet, portrait — 820 × 1180 <a class="header-anchor" href="#tablet-portrait-—-820-×-1180" aria-label="Permalink to &quot;Tablet, portrait — 820 × 1180&quot;">​</a></h2><figure class="shot"><img src="'+s+'" alt="820 by 1180 tablet window with the top bar on one row and a single, full-width compare column"><figcaption>820 × 1180: top bar on one row, sidebar in a drawer, compare still a single column, toolbar over two rows.</figcaption></figure><p>At 820 px the top bar stays on a single row and the sidebar stays a drawer, but the compare stage is still one column wide — the language panes are stacked rather than side by side. The <strong>Language</strong> chips work as on the phone, and the toolbar folds into two rows: language and view controls first, then the annotation tools. Notes open as a drawer over the stage.</p><h2 id="tablet-landscape-—-1180-×-820" tabindex="-1">Tablet, landscape — 1180 × 820 <a class="header-anchor" href="#tablet-landscape-—-1180-×-820" aria-label="Permalink to &quot;Tablet, landscape — 1180 × 820&quot;">​</a></h2><figure class="shot"><img src="'+r+'" alt="1180 by 820 tablet window with the sidebar open and three language panes side by side"><figcaption>1180 × 820: sidebar open, three language panes side by side, notes as a drawer.</figcaption></figure><p>At 1180 px the sidebar (240 px) is back, and the three language panes sit in one row at roughly 290 px each. Notes stay a drawer at this width and open over the stage. The toolbar keeps two rows — language and alignment controls on top, annotation tools below — while <strong>Export HTML</strong> stays in the top bar.</p><div class="tip custom-block"><p class="custom-block-title">Capturing your own layouts</p><p>Resize the browser window rather than zooming the page: the breakpoints follow the viewport width, and the notes column and sidebar only change places when the window itself crosses them.</p></div>',18)])])}const v=n(p,[["render",d]]);export{_ as __pageData,v as default};
